"use strict";

// Records the JavaScript MCP catalog (initialize instructions and the
// tools/list entries) at the Node release's size defaults, for the Go port's
// catalog test. Run once from the repository root, with node_modules
// installed and no size settings in the environment:
//
//   node internal/mcp/testdata/dump-catalog.js > internal/mcp/testdata/js-catalog.json
//
// The output is the spec the Go catalog is compared against under
// nodedefaults.Setenv; it is not regenerated by the Go tests.

const path = require("node:path");

const root = path.resolve(__dirname, "../../..");
for (const name of Object.keys(process.env)) {
  if (/^(PAGES_|MAX_HTML_BYTES|PAGE_UPLOAD_|DASHBOARD_|CONTENT_|MCP_)/.test(name)) delete process.env[name];
}
const { createServer, INSTRUCTIONS, DATA_UPDATE_INSTRUCTIONS } = require(path.join(root, "lib/mcp.js"));

(async () => {
  const server = createServer(null);
  const response = await server.handleRequest({ jsonrpc: "2.0", id: 1, method: "tools/list", params: {} });
  const catalog = {
    instructions: INSTRUCTIONS,
    data_update_instructions: DATA_UPDATE_INSTRUCTIONS,
    tools: response.result.tools,
  };
  process.stdout.write(`${JSON.stringify(catalog, null, 1)}\n`);
  process.exit(0);
})();
